function hasBalancedBrackets(text) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const stack = [];

  for (const character of text) {
    if ('([{'.includes(character)) {
      stack.push(character);
    } else if (pairs[character] && stack.pop() !== pairs[character]) {
      return false;
    }
  }

  return stack.length === 0;
}

