function twoSum(values, target) {
  const indicesByValue = new Map();

  for (let index = 0; index < values.length; index++) {
    const complement = target - values[index];

    if (indicesByValue.has(complement)) {
      return [indicesByValue.get(complement), index];
    }

    indicesByValue.set(values[index], index);
  }

  return null;
}

